// SPDX-License-Identifier: Apache-2.0
// Generated files are shipped in wheels; Node is only needed by maintainers.
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const {build, version} = require("esbuild");
const root = path.resolve(__dirname, "..");
const check = process.argv.includes("--check");
const entries = [
  [
    "plugins/fd-lab/texstage_fd_lab/web/engine.mjs",
    "plugins/fd-lab/texstage_fd_lab/web/engine.worker.mjs"
  ],
  [
    "plugins/transaction-engine/texstage_transaction_engine/web/schedule.mjs",
    "plugins/transaction-engine/texstage_transaction_engine/web/schedule.worker.mjs"
  ],
  [
    "plugins/relational-lab/texstage_relational_lab/web/engine.mjs",
    "plugins/relational-lab/texstage_relational_lab/web/engine.worker.mjs"
  ]
];
(async () => {
  for (const [entry, output] of entries) {
    const result = await build({
      absWorkingDir: root, entryPoints: [entry], outfile: output,
      bundle: true, format: "esm", platform: "browser", target: "es2022",
      charset: "utf8", legalComments: "inline", write: false, metafile: true,
      banner: {js: "// SPDX-License-Identifier: Apache-2.0\n// Generated by maintenance/build_worker_modules.cjs (esbuild " + version + "). Do not edit."},
    });
    assert.equal(result.outputFiles.length, 1, "Worker entries must be self-contained");
    for (const metadata of Object.values(result.metafile.outputs)) {
      assert.deepEqual(metadata.imports, [], "Worker bundles must not import other modules");
    }
    const file = path.join(root, output);
    const bytes = result.outputFiles[0].contents;
    if (check) {
      assert(fs.existsSync(file) && Buffer.from(bytes).equals(fs.readFileSync(file)),
        output + " is stale; run npm run build:workers");
    } else {
      fs.writeFileSync(file, bytes);
    }
    console.log((check ? "Verified " : "Generated ") + output);
  }
})().catch(error => { console.error(error); process.exitCode = 1; });
